import Foundation

// MARK: - Obeying God Theme Content (20 Entries)

extension ContentLibrary {

    static let obeyingGodThemeContent: [DayContent] = [
        DayContent(
            scriptureReference: "John 14:15",
            scriptureText: "If you love me, keep my commands.",
            devotionalTitle: "Obedience Is Love's Language",
            devotionalText: "Jesus makes it simple: love and obedience are the same thing. You don't prove love through feelings alone — you prove it through action. Keeping God's commands isn't about earning His love; it's about expressing yours. When obedience feels hard, remember what it really is: love in action.",
            prayerText: "Jesus, I love You. And I want my obedience to prove it. Help me keep Your commands not out of duty but out of genuine love. When obedience feels difficult, remind me that it's my way of saying 'I love You.' In Jesus' name, amen.",
            reflectionPrompt: "If obedience is love's language, what is your obedience saying to God right now?",
            actionSteps: ["Identify one command of Jesus you've been neglecting and obey it today as an act of love", "Write 'Obedience = Love' where you'll see it throughout the day"]
        ),
        DayContent(
            scriptureReference: "1 Samuel 15:22",
            scriptureText: "But Samuel replied: 'Does the Lord delight in burnt offerings and sacrifices as much as in obeying the Lord? To obey is better than sacrifice, and to heed is better than the fat of rams.'",
            devotionalTitle: "Obedience Over Religious Activity",
            devotionalText: "Saul offered sacrifices instead of obeying God's clear command. He substituted religious activity for actual obedience. It's easy to do the same — attending church, giving money, serving on teams — while ignoring what God has specifically asked of you. God isn't impressed by your religious résumé. He wants your obedience.",
            prayerText: "Lord, forgive me for the times I've substituted religious activity for actual obedience. I don't want to give You sacrifices when You're asking for submission. Show me where I've been busy for You instead of obedient to You. I choose obedience today. In Jesus' name, amen.",
            reflectionPrompt: "Is there an area where you've been substituting religious activity for the specific obedience God is asking for?",
            actionSteps: ["Ask God: 'What have You specifically asked me to do that I haven't done?'", "Do one thing today that is pure obedience, not just religious habit"]
        ),
        DayContent(
            scriptureReference: "Deuteronomy 5:33",
            scriptureText: "Walk in obedience to all that the Lord your God has commanded you, so that you may live and prosper and prolong your days in the land that you will possess.",
            devotionalTitle: "The Path That Leads to Life",
            devotionalText: "Obedience isn't restrictive — it's the path to life, prosperity, and longevity. God's commands aren't arbitrary rules; they're directions to the best possible life. When you walk in obedience, you walk in blessing. Disobedience isn't freedom — it's taking the path that leads away from everything good God has planned.",
            prayerText: "Lord, I want to walk in the path of life. I choose obedience because Your commands lead to blessing. Help me see Your instructions not as restrictions but as directions to the life You've planned for me. I trust that Your way is the best way. In Jesus' name, amen.",
            reflectionPrompt: "Have you been viewing God's commands as restrictions or as directions to life?",
            actionSteps: ["Reframe one of God's commands as a direction to blessing rather than a restriction", "Walk in obedience in one specific area today and notice the peace it brings"]
        ),
        DayContent(
            scriptureReference: "Luke 6:46",
            scriptureText: "Why do you call me, 'Lord, Lord,' and do not do what I say?",
            devotionalTitle: "Lord Means Boss",
            devotionalText: "Jesus asks a piercing question: Why do you call me Lord but not obey me? The word 'Lord' means authority, boss, master. If Jesus is Lord, His words aren't suggestions — they're instructions. You can't call Jesus Lord and then live like you're in charge. Lordship without obedience is just a nice word.",
            prayerText: "Jesus, You are Lord — not just in title, but in reality. Forgive me for calling You Lord while living like I'm in charge. I submit to Your authority today. Your words are not suggestions; they're my instructions. Help me live under Your lordship in every area. In Jesus' name, amen.",
            reflectionPrompt: "In what areas of your life have you called Jesus Lord but acted as your own boss?",
            actionSteps: ["Identify one area where you've been in charge instead of Jesus and surrender it", "Before each decision today, ask 'What would my Lord want me to do?'"]
        ),
        DayContent(
            scriptureReference: "James 1:22",
            scriptureText: "Do not merely listen to the word, and so deceive yourselves. Do what it says.",
            devotionalTitle: "Hearing Without Doing Is Self-Deception",
            devotionalText: "James is blunt: if you hear God's Word but don't act on it, you're deceiving yourself. You can attend every Bible study, listen to every sermon, read every devotional — but if nothing changes in how you live, you've only fooled yourself into thinking you're growing. Real growth shows up in action, not just understanding.",
            prayerText: "Lord, don't let me be a hearer only. Every time I encounter Your Word, move me to action. Protect me from the self-deception of knowledge without obedience. I want to be a doer — someone whose life changes because of what they hear. In Jesus' name, amen.",
            reflectionPrompt: "What truth have you heard recently that you haven't acted on yet?",
            actionSteps: ["Take one thing you learned from Scripture this week and put it into practice today", "After reading the Bible today, write down one specific action you'll take in response"]
        ),
        DayContent(
            scriptureReference: "Genesis 12:1-4",
            scriptureText: "The Lord had said to Abram, 'Go from your country, your people and your father's household to the land I will show you.' ... So Abram went, as the Lord had told him.",
            devotionalTitle: "Go Without Knowing Where",
            devotionalText: "God told Abraham to go — but didn't tell him where. Abraham obeyed anyway. Sometimes God gives you the next step without revealing the destination. He says 'go' and waits to see if you'll move before He shows you where. Obedience often means taking the first step in faith, trusting that God will reveal the rest as you walk.",
            prayerText: "Lord, like Abraham, I'll go even when I don't know where. I trust You enough to take the first step without seeing the whole path. Give me the faith to obey when all I have is Your command and Your character. I go as You've told me. In Jesus' name, amen.",
            reflectionPrompt: "Is God asking you to take a step of obedience without showing you the full picture?",
            actionSteps: ["Take one step of obedience today that requires faith — even without seeing the outcome", "Write down what God is asking you to 'go' toward and commit to the first step"]
        ),
        DayContent(
            scriptureReference: "Philippians 2:8",
            scriptureText: "And being found in appearance as a man, he humbled himself by becoming obedient to death — even death on a cross!",
